export const datasetById = (id: DatasetId): DatasetMeta =>
  DATASETS.find((d) => d.id === id) ?? DATASETS[0]!;

export interface DatasetOptions {
  rows: number;
  seed: number;
  conditionId: ChannelConditionId;
  frequencyHz: number;
  bandwidthHz: number;
  txPowerDbm: number;
  architecture: ArchitectureId;
}

export const DEFAULT_DATASET_OPTIONS: DatasetOptions = {
  rows: 120,
  seed: 20260921,
  conditionId: 'nlos-urban',
  frequencyHz: 28e9,
  bandwidthHz: 100e6,
  txPowerDbm: 24,
  architecture: 'cnn',
};

export type DatasetRow = Record<string, string | number | boolean>;

export interface Dataset {
  meta: DatasetMeta;
  options: DatasetOptions;
  rows: DatasetRow[];
  generatedAt: string;
}

const round = (value: number, places = 3): number => Number(value.toFixed(places));

function wirelessChannelRows(options: DatasetOptions): DatasetRow[] {
  const random = makeRng(options.seed);
  const condition = conditionById(options.conditionId);
  const rows: DatasetRow[] = [];
  const noiseFloor = noisePowerDbm(options.bandwidthHz, 7);

  for (let i = 0; i < options.rows; i += 1) {
    const x = 10 + random() * 190;
    const y = (random() - 0.5) * 60;
    const distance = Math.hypot(x, y, 8.5);
    const h = ricianFading(condition.ricianKDb, random);
    const magnitude = abs(h);

    const pathLoss =
      freeSpacePathLossDb(distance, options.frequencyHz) +
      (condition.pathLossExponent - 2) * 10 * Math.log10(Math.max(1, distance)) +
      condition.blockageDb;
    const rxPower = options.txPowerDbm + 25 - pathLoss + 20 * Math.log10(Math.max(magnitude, 1e-6));
    const snrDb = rxPower - noiseFloor;

    rows.push({
      userId: i + 1,
      x: round(x, 2),
      y: round(y, 2),
      distanceM: round(distance, 2),
      condition: condition.label,
      csiReal: round(h.re, 5),
      csiImag: round(h.im, 5),
      csiMagnitudeDb: round(20 * Math.log10(Math.max(magnitude, 1e-6)), 2),
      csiPhaseRad: round(arg(h), 4),
      pathLossDb: round(pathLoss, 2),
      rxPowerDbm: round(rxPower, 2),
      noiseFloorDbm: round(noiseFloor, 2),
      snrDb: round(snrDb, 2),
      modulation: selectModulation(snrDb)?.name ?? 'outage',
      capacityMbps: round(shannonCapacityBps(options.bandwidthHz, snrDb) / 1e6, 2),
    });
  }
  return rows;
}

function irsRows(options: DatasetOptions): DatasetRow[] {
  const random = makeRng(options.seed + 991);
  const condition = conditionById(options.conditionId);
  const rows: DatasetRow[] = [];
  const elementChoices = [16, 32, 64, 128, 256];
  const bitChoices = [0, 1, 2, 3];

  const link: LinkConfig = {
    txPowerDbm: options.txPowerDbm,
    frequencyHz: options.frequencyHz,
    bandwidthHz: options.bandwidthHz,
    txGainDbi: 15,
    rxGainDbi: 10,
    noiseFigureDb: 7,
    elementGainDbi: 3,
  };

  for (let i = 0; i < options.rows; i += 1) {
    const elements = elementChoices[Math.floor(random() * elementChoices.length)]!;
    const phaseBits = bitChoices[Math.floor(random() * bitChoices.length)]!;
    const reflection = round(0.7 + random() * 0.3, 2);
    const userX = 30 + random() * 120;
    const userY = (random() - 0.5) * 40;
    const irsX = 10 + random() * (userX - 10);
    const irsY = 4 + random() * 14;

    const irs: IrsConfig = {
      elementCount: elements,
      reflectionCoefficient: reflection,
      phaseBits,
      transmitter: { x: 0, y: 0, z: 10 },
      surface: { x: irsX, y: irsY, z: 8 },
      receiver: { x: userX, y: userY, z: 1.5 },
    };

    const channels = generateIrsChannels(irs, link, condition, random);
    const optimised = quantisePhases(closedFormPhases(channels), phaseBits);
    const scrambled = randomPhases(elements, random);

    let sumCos = 0;
    let sumSin = 0;
    for (const phase of optimised) {
      sumCos += Math.cos(phase);
      sumSin += Math.sin(phase);
    }
    const resultant = Math.hypot(sumCos, sumSin) / Math.max(1, optimised.length);

    const optimisedSnr = snrForPhases(channels, optimised);
    const randomSnr = snrForPhases(channels, scrambled);

    rows.push({
      configId: i + 1,
      userX: round(userX, 2),
      userY: round(userY, 2),
      irsX: round(irsX, 2),
      irsY: round(irsY, 2),
      elements,
      phaseBits,
      reflection,
      meanPhaseRad: round(Math.atan2(sumSin, sumCos), 4),
      // Circular standard deviation, √(−2 ln R). An arithmetic standard
      // deviation of angles is meaningless across the ±π branch cut.
      phaseSpreadRad: round(Math.sqrt(-2 * Math.log(Math.max(resultant, 1e-6))), 4),
      randomSnrDb: round(randomSnr, 2),
      optimisedSnrDb: round(optimisedSnr, 2),
      gainDb: round(optimisedSnr - randomSnr, 2),
      rateMbps: round(shannonCapacityBps(options.bandwidthHz, optimisedSnr) / 1e6, 2),
    });
  }
  return rows;
}

async function semanticRows(options: DatasetOptions): Promise<DatasetRow[]> {
  const rows: DatasetRow[] = [];
  const snrGrid = [-3, 0, 4, 8, 12, 16, 22];
  const useGrid = [32, 16, 8];
  const perCombination = Math.max(1, Math.ceil(options.rows / (snrGrid.length * useGrid.length)));

  let id = 1;
  for (const channelUses of useGrid) {
    for (const snrDb of snrGrid) {
      const run = await runSemantic({
        architecture: options.architecture,
        channelUses,
        snrDb,
        importance: 0.5,
        codeRate: 0.75,
        sceneSeed: options.seed + id * 17,
        sampleCount: perCombination,
        // Without this the run returns only the four samples kept for display,
        // so this generator silently topped out at 4 × 21 = 84 rows however
        // far the Rows slider was dragged.
        keepAllSamples: true,
      });
      run.samples.forEach((sample: SemanticSampleResult) => {
        if (rows.length >= options.rows) return;
        rows.push({
          sceneId: id,
          sceneClass: SCENE_LABELS[sample.descriptor.sceneClass],
          snrDb,
          channelUses,
          bandwidthRatio: round(channelUses / 256, 4),
          architecture: options.architecture,
          neuralPsnrDb: round(sample.neuralPsnrDb, 2),
          neuralSsim: round(sample.neuralSsim, 4),
          classicalPsnrDb: round(sample.classicalPsnrDb, 2),
          classicalSsim: round(sample.classicalSsim, 4),
          classicalLost: sample.classicalLost,
        });
        id += 1;
      });
    }
  }
  return rows;
}

export async function generateDatasetRows(
  id: DatasetId,
  options: DatasetOptions,
): Promise<Dataset> {
  const meta = datasetById(id);
  let rows: DatasetRow[];
  switch (id) {
    case 'semantic':
      rows = await semanticRows(options);
      break;
    case 'irs-optimisation':
      rows = irsRows(options);
      break;
    case 'wireless-channel':
    default:
      rows = wirelessChannelRows(options);
      break;
  }
  return { meta, options, rows, generatedAt: new Date().toISOString() };
}

/** Escapes a CSV field — quotes, commas and newlines all need handling. */
const csvField = (value: string | number | boolean): string => {
  const text = String(value);
  return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
};

/**
 * CSV with a provenance header.
 *
 * The comment lines are the important part. A file of numbers that leaves this
 * page with no statement of where it came from will eventually be pasted into
 * something that treats it as data from a real network.
 */
export function toCsv(dataset: Dataset): string {
  const keys = dataset.meta.columns.map((c) => c.key);
  const header = [
    `# ${dataset.meta.title}`,
    '# SIMULATED DATA — generated by the AI for 6G Virtual Live Lab. Not a measurement of any real network.',
    `# ${dataset.meta.provenance}`,
    `# generated ${dataset.generatedAt}`,
    `# seed=${dataset.options.seed} rows=${dataset.rows.length} condition=${dataset.options.conditionId} f=${dataset.options.frequencyHz / 1e9}GHz B=${dataset.options.bandwidthHz / 1e6}MHz Ptx=${dataset.options.txPowerDbm}dBm`,
    dataset.meta.columns
      .map((c) => csvField(c.unit ? `${c.label} (${c.unit})` : c.label))
      .join(','),
  ];
  const body = dataset.rows.map((row) => keys.map((key) => csvField(row[key] ?? '')).join(','));
  return [...header, ...body].join('\n');
}

export function toJson(dataset: Dataset): string {
  return JSON.stringify(
    {
      dataset: dataset.meta.id,
      title: dataset.meta.title,
      disclaimer:
        'SIMULATED DATA generated by the AI for 6G Virtual Live Lab. Not a measurement of any real network.',
      provenance: dataset.meta.provenance,
      generatedAt: dataset.generatedAt,
      options: dataset.options,
      columns: dataset.meta.columns,
      rows: dataset.rows,
    },
    null,
    2,
  );
}

